{{-- Message text with its links clickable ($text = Alpine expression). Links open in a new tab so the call keeps running; kept on one line (the parent uses whitespace-pre-wrap). --}}<template x-for="(part, pi) in linkify({{ $text }})" :key="pi"><span><template x-if="part.href"><a :href="part.href" target="_blank" rel="noopener noreferrer nofollow" class="{{ $linkClass ?? 'underline decoration-1 underline-offset-2 hover:opacity-80' }}" x-text="part.text"></a></template><template x-if="!part.href"><span x-text="part.text"></span></template></span></template>